// Catalog JSON refers to images by file name; this resolves them to bundled URLs.
const files = import.meta.glob("../assets/img/*", { eager: true, import: "default" });

const byName = Object.fromEntries(
  Object.entries(files).map(([path, url]) => [path.split("/").pop(), url])
);

export const imageUrl = (name) => (name ? byName[name] ?? null : null);

// Art generated by tools/comfy lives in src/assets/gen/<kind>/<id>.webp and
// takes priority over the hand-made image. Deleting the file reverts to it.
const generated = import.meta.glob("../assets/gen/*/*.webp", { eager: true, import: "default" });

const generatedByKey = Object.fromEntries(
  Object.entries(generated).map(([path, url]) => [path.split("/").slice(-2).join("/").replace(/\.webp$/, ""), url])
);

export const generatedArt = (kind, id) => generatedByKey[`${kind}/${id}`] ?? null;

export const artUrl = (kind, entry) => generatedArt(kind, entry.id) ?? imageUrl(entry.img);
